(function(root){'use strict';const version=root.FORMA_SCORM_VERSION||'demo',is2004=version==='2004',logs=[];let adapter=null,initialized=false,terminated=false,unavailable=false;const started=Date.now();const methods=is2004?{init:'Initialize',get:'GetValue',set:'SetValue',commit:'Commit',end:'Terminate',error:'GetLastError'}:{init:'LMSInitialize',get:'LMSGetValue',set:'LMSSetValue',commit:'LMSCommit',end:'LMSFinish',error:'LMSGetLastError'};const fields=is2004?{location:'cmi.location',time:'cmi.session_time',exit:'cmi.exit'}:{location:'cmi.core.lesson_location',time:'cmi.core.session_time',exit:'cmi.core.exit'};function log(message){logs.push(message);const node=root.document?.getElementById('sessionLog');if(node)node.textContent=logs.join('\n')}
function find(start){let win=start;for(let i=0;win&&i<100;i++){try{if(win[is2004?'API_1484_11':'API'])return win[is2004?'API_1484_11':'API'];if(win.parent===win)break;win=win.parent}catch{break}}return null}
function call(name,...args){try{const value=adapter[methods[name]](...args);log(methods[name]+'('+args.map(v=>JSON.stringify(v)).join(', ')+') → '+String(value));return value}catch{log('Falha ao chamar '+methods[name]);return 'false'}}
function read(key){if(!initialized)return '';const value=call('get',key);return value==='false'?'':String(value??'')}
function write(key,value){if(!initialized||terminated)return false;const ok=String(call('set',key,String(value)))==='true';if(!ok){log('Não foi possível gravar '+key);unavailable=true}return ok}
function sessionTime(ms,v){const seconds=Math.max(0,ms/1000);if(v==='2004')return 'PT'+seconds.toFixed(2)+'S';const ticks=Math.floor(Math.max(0,ms)/10),h=Math.floor(ticks/360000),m=Math.floor(ticks/6000)%60,s=((ticks%6000)/100).toFixed(2).padStart(5,'0');return String(h).padStart(4,'0')+':'+String(m).padStart(2,'0')+':'+s}
function commit(){if(!initialized||terminated)return false;write(fields.time,sessionTime(Date.now()-started,version));const ok=String(call('commit',''))==='true';if(!ok)unavailable=true;return ok}
function localRead(){try{return JSON.parse(root.localStorage.getItem('forma-course-demo-v1'))}catch{return null}}
function load(){if(version==='demo'){log('Demonstração: progresso salvo apenas neste navegador.');return localRead()}adapter=find(root);try{if(!adapter&&root.opener)adapter=find(root.opener)}catch{}if(!adapter){log('API do LMS não encontrada. Abra este pacote pelo LMS para registrar resultados.');return null}initialized=String(call('init',''))==='true';if(!initialized){log('Inicialização recusada pelo LMS.');return null}let data=null;try{data=JSON.parse(read('cmi.suspend_data')||'null')}catch{log('Retomada inválida: uma nova tentativa local será iniciada.')}if(!data){write(is2004?'cmi.completion_status':'cmi.core.lesson_status','incomplete');if(is2004)write('cmi.success_status','unknown');commit()}return data}
function save(state){if(version==='demo'){try{root.localStorage.setItem('forma-course-demo-v1',JSON.stringify(state));log('Progresso demonstrativo salvo.');return true}catch{unavailable=true;log('Armazenamento local indisponível.');return false}}if(!initialized)return false;write('cmi.suspend_data',JSON.stringify(state));write(fields.location,String(state.step));write(fields.exit,state.finished?'':'suspend');if(state.finished){const score=state.answers.filter(a=>a.correct).length*25;write(is2004?'cmi.score.min':'cmi.core.score.min',0);write(is2004?'cmi.score.max':'cmi.core.score.max',100);write(is2004?'cmi.score.raw':'cmi.core.score.raw',score);if(is2004){write('cmi.score.scaled',score/100);write('cmi.completion_status','completed');write('cmi.success_status',score>=75?'passed':'failed')}else write('cmi.core.lesson_status',score>=75?'passed':'failed')}return commit()&&!unavailable}
function end(){if(!initialized||terminated)return;commit();call('end','');terminated=true}
root.FormaScorm={load,save,end,sessionTime,logs,get mode(){return version==='demo'?(unavailable?'Demonstração · gravação local indisponível':'Demonstração · dados locais'):initialized&&!unavailable?'Conectado ao LMS · SCORM '+version:'SCORM '+version+' · registro no LMS indisponível'}};root.addEventListener('pagehide',end);root.addEventListener('beforeunload',end)
})(window);

